 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Find the full-width/full-height 2 marker and the colored shape.
    marker_rows = [r for r in range(h) if all(v == 2 for v in grid[r])]
    marker_cols = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    shape = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != 2]
    if not shape:
        return [row[:] for row in grid]
    minr = min(r for r, c, v in shape); maxr = max(r for r, c, v in shape)
    minc = min(c for r, c, v in shape); maxc = max(c for r, c, v in shape)
    out = [row[:] for row in grid]
    # Translate the shape toward the marker until it is adjacent. Then mark
    # the opposite edge with a full stripe of color 8.
    if marker_rows:
        mr = marker_rows[0]
        if mr > maxr:
            dr = mr - maxr - 1
            stripe = minr + dr - 1
        else:
            dr = mr - minr + 1
            stripe = maxr + dr + 1
        for r, c, v in shape:
            out[r][c] = bg
        for r, c, v in shape:
            out[r + dr][c] = v
        if 0 <= stripe < h:
            out[stripe] = [8] * w
    elif marker_cols:
        mc = marker_cols[0]
        if mc > maxc:
            dc = mc - maxc - 1
            stripe = minc + dc - 1
        else:
            dc = mc - minc + 1
            stripe = maxc + dc + 1
        for r, c, v in shape:
            out[r][c] = bg
        for r, c, v in shape:
            out[r][c + dc] = v
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8
    return out
